def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a 2D array to count the number of chatting pairs
    # that can be separated by adding an aisle in each possible position
    count_array = [[0] * (N + 1) for _ in range(M + 1)]

    for chatting_pair in chatting_pairs:
        # Get the positions of the two students in the chatting pair
        x1, y1 = chatting_pair[0]
        x2, y2 = chatting_pair[1]

        # Handle the case where the students are in the same row
        if y1 == y2:
            for i in range(N + 1):
                if i != y1:
                    count_array[x1][i] += 1

        # Handle the case where the students are in the same column
        if x1 == x2:
            for i in range(M + 1):
                if i != x1:
                    count_array[i][y1] += 1

        # Handle the case where the students are in different rows and columns
        else:
            for i in range(M + 1):
                for j in range(N + 1):
                    if i != x1 and j != y1 and i != x2 and j != y2:
                        count_array[i][j] += 1

    # Initialize the row and column indices for the aisles
    row_indices = [i for i in range(1, M + 1)]
    col_indices = [j for j in range(1, N + 1)]

    # Select the most effective positions for the aisles
    for i in range(K):
        max_count = 0
        max_row_index = None
        for row_index in row_indices:
            count = count_array[row_index][col_indices[0]]
            if count > max_count:
                max_count = count
                max_row_index = row_index
        row_indices.remove(max_row_index)
    for j in range(L):
        max_count = 0
        max_col_index = None
        for col_index in col_indices:
            count = count_array[row_indices[0]][col_index]
            if count > max_count:
                max_count = count
                max_col_index = col_index
        col_indices.remove(max_col_index)

    # Return the final row and column indices for the aisles
    return (' '.join(map(str, row_indices)), ' '.join(map(str, col_indices)))
