def preorder_traversal(inorder, postorder):
    inorder_map = {char: index for index, char in enumerate(inorder)}
    postorder_map = {char: index for index, char in enumerate(postorder)}

    def helper(start, end):
        if start > end:
            return ''
        if start == end:
            return inorder[start]

        root = postorder[end]
        root_index = inorder_map[root]
        left_size = root_index - start

        left = helper(start, start + left_size - 1)
        right = helper(root_index + 1, end - 1)

        return left + root + right

    return helper(0, len(inorder) - 1)
