def preorder_traversal(inorder, postorder):
    inorder_idx = {c: i for i, c in enumerate(inorder)}
    postorder_idx = {c: i for i, c in enumerate(postorder)}
    def helper(start, end):
        if start > end:
            return ''
        if start == end:
            return inorder[start]
        root = postorder[postorder_idx[inorder[start]]]
        left = helper(start, inorder_idx[root] - 1)
