from enum import Enum
from typing import List

class Tree:
    def __init__(self, position: int):
        self.position = position
        self.cleared = False

class ClearingType(Enum):
    Left = 1
    Right = 2

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    trees = [Tree(i) for i in range(l)]
    for (start, end) in areas:
        for tree in trees:
            if tree.position == start or tree.position == end:
                tree.cleared = True
                continue
            if start <= tree.position <= end:
                if ClearingType.Left and tree.position < end:
                    tree.cleared = True
                elif ClearingType.Right and tree.position > start:
                    tree.cleared = True
    return len(list(filter(lambda x: not x.cleared, trees)))

